/**
 * Read-only Audi/Arteon DS4 catch-up preflight (no processJob, no writes).
 */
const crypto = require('crypto');
const path = require('path');
const { PrismaClient } = require('@prisma/client');

const ORG = 'faa710c9-6d91-4079-a7d5-91fdccdec14a';
const AUDI = 'c10351f8-b6a2-4258-947f-631aeaa6d359';
const ARTEON = '8c850ff1-4201-432b-af2e-2711dbc7ca48';
const ADAPTER = 'tire-ds4-shadow-input-v1.1.1';
const TERMINAL = [
  '00000000-0000-4000-a000-000000000001',
  '00000000-0000-4000-a000-000000000002',
];
const backendRoot =
  process.argv.find((a) => a.startsWith('--backend='))?.slice(10) ||
  '/opt/synqdrive/current/backend';
const outPath =
  process.argv.find((a) => a.startsWith('--out='))?.slice(6) ||
  '/tmp/tire-ds4-phase2-preflight.json';

function loadDist(rel) {
  return require(path.join(backendRoot, 'dist/src', rel));
}

function manifestHash(rows) {
  const canonical = [...rows]
    .sort((a, b) => a.tireTripUsageLedgerId.localeCompare(b.tireTripUsageLedgerId))
    .map((r) => ({
      ledgerId: r.tireTripUsageLedgerId,
      tripId: r.tripId,
      vehicleId: r.vehicleId,
      runId: r.expectedRunId,
      adapter: ADAPTER,
    }));
  return crypto.createHash('sha256').update(JSON.stringify(canonical)).digest('hex');
}

async function catchupCandidates(prisma, vehicleIds) {
  return prisma.$queryRaw`
    WITH latest_succeeded AS (
      SELECT DISTINCT ON (r.organization_id, r.vehicle_id, r.trip_id)
        r.organization_id, r.vehicle_id, r.trip_id, r.id AS run_id
      FROM di_v0_motion_core_shadow_runs_v1 r
      WHERE r.shadow_status = 'SUCCEEDED' AND r.organization_id = ${ORG}
      ORDER BY r.organization_id, r.vehicle_id, r.trip_id, r.created_at DESC
    )
    SELECT l.id AS tire_trip_usage_ledger_id, l.organization_id, l.vehicle_id, l.trip_id,
           l.tire_setup_id, l.distance_km, l.invalidated_at
    FROM tire_trip_usage_ledger l
    INNER JOIN latest_succeeded ls
      ON ls.organization_id = l.organization_id AND ls.vehicle_id = l.vehicle_id AND ls.trip_id = l.trip_id
    LEFT JOIN tire_ds4_motion_shadow_input_v1 mat
      ON mat.tire_trip_usage_ledger_id = l.id AND mat.adapter_version = ${ADAPTER}
      AND mat.di_v0_motion_core_shadow_run_id = ls.run_id
    WHERE l.invalidated_at IS NULL AND l.organization_id = ${ORG}
      AND l.vehicle_id = ANY(${vehicleIds}::text[]) AND mat.id IS NULL
    ORDER BY l.processed_at ASC`;
}

async function main() {
  const prisma = new PrismaClient();
  const { TireDs4ShadowRepository } = loadDist(
    'modules/vehicle-intelligence/tires/ds4-shadow/tire-ds4-shadow.repository',
  );
  const { DiV0MotionCoreShadowTripMapReadService } = loadDist(
    'modules/vehicle-intelligence/driving-intelligence/motion-core-shadow-worker/di-v0-motion-core-shadow-trip-map-read.service',
  );
  const { mapDs4TripMapToTireShadowInput, eventQualityCoverageFromPayload } = loadDist(
    'modules/vehicle-intelligence/tires/ds4-shadow/tire-ds4-shadow-input.mapper',
  );

  const repository = new TireDs4ShadowRepository(prisma);
  const tripRead = new DiV0MotionCoreShadowTripMapReadService(prisma);

  const vehicleIds = [AUDI, ARTEON];
  const raw = await catchupCandidates(prisma, vehicleIds);

  const candidates = [];
  const issues = [];
  const qualityByVehicle = {
    [AUDI]: { temporal: {}, eventQuality: {}, readStatus: {}, m3: { withM3: 0, total: 0 } },
    [ARTEON]: { temporal: {}, eventQuality: {}, readStatus: {}, m3: { withM3: 0, total: 0 } },
  };

  for (const row of raw) {
    const ledgerId = row.tire_trip_usage_ledger_id;
    const vehicleId = row.vehicle_id;
    const tripId = row.trip_id;

    if (row.organization_id !== ORG) {
      issues.push({ ledgerId, code: 'ORG_MISMATCH' });
      continue;
    }
    if (row.invalidated_at) {
      issues.push({ ledgerId, code: 'LEDGER_INVALIDATED' });
      continue;
    }

    const terminal = await repository.hasTerminalMarker(ledgerId, ADAPTER);
    if (terminal) {
      issues.push({ ledgerId, code: 'TERMINAL_MARKER' });
      continue;
    }

    const run = await prisma.diV0MotionCoreShadowRunV1.findFirst({
      where: { organizationId: ORG, vehicleId, tripId, shadowStatus: 'SUCCEEDED' },
      orderBy: { createdAt: 'desc' },
      select: {
        id: true,
        combinedInputIdentity: true,
        pinnedSnapshotHash: true,
        contentFingerprint: true,
        shadowBundleVersion: true,
        shadowStatus: true,
      },
    });
    if (!run?.combinedInputIdentity || !run.pinnedSnapshotHash || !run.contentFingerprint) {
      issues.push({ ledgerId, code: 'RUN_IDENTITY_INCOMPLETE' });
      continue;
    }

    const existingTarget = await prisma.tireDs4MotionShadowInputV1.findFirst({
      where: {
        tireTripUsageLedgerId: ledgerId,
        adapterVersion: ADAPTER,
        diV0MotionCoreShadowRunId: run.id,
      },
    });
    if (existingTarget) {
      issues.push({ ledgerId, code: 'ADAPTER_ALREADY_PRESENT' });
      continue;
    }

    const read = await tripRead.readForTrip(ORG, vehicleId, tripId);
    const qv = qualityByVehicle[vehicleId];
    qv.readStatus[read.status] = (qv.readStatus[read.status] || 0) + 1;

    if (read.status !== 'SUCCEEDED' && read.status !== 'SUCCEEDED_EMPTY') {
      issues.push({ ledgerId, code: 'READ_NOT_SUCCEEDED', status: read.status, failureCode: read.failureCode });
      continue;
    }
    if (read.runId !== run.id) {
      issues.push({ ledgerId, code: 'RUN_ID_MISMATCH', sql: run.id, read: read.runId });
      continue;
    }
    if (!read.combinedInputIdentity || !read.pinnedSnapshotHash) {
      issues.push({ ledgerId, code: 'READ_IDENTITY_MISSING' });
      continue;
    }

    const ledger = await prisma.tireTripUsageLedger.findFirst({
      where: { id: ledgerId },
      select: { distanceKm: true, tripStartedAt: true, tripEndedAt: true },
    });

    let payload;
    try {
      payload = mapDs4TripMapToTireShadowInput(read, {
        tripDistanceKm: ledger?.distanceKm ?? null,
        tripStartedAt: ledger?.tripStartedAt ?? null,
        tripEndedAt: ledger?.tripEndedAt ?? null,
      });
    } catch (e) {
      issues.push({ ledgerId, code: 'MAP_FAILED', error: String(e.message || e) });
      continue;
    }

    const eq = eventQualityCoverageFromPayload(payload);
    const tc = payload.temporalCoverage;
    qv.temporal[tc] = (qv.temporal[tc] || 0) + 1;
    qv.eventQuality[eq] = (qv.eventQuality[eq] || 0) + 1;
    qv.m3.total += 1;
    const accM3 = payload.acceleration?.okM3EventCount ?? 0;
    const decM3 = payload.deceleration?.okM3EventCount ?? 0;
    if (accM3 + decM3 > 0) qv.m3.withM3 += 1;

    candidates.push({
      tireTripUsageLedgerId: ledgerId,
      organizationId: ORG,
      vehicleId,
      tripId,
      tireSetupId: row.tire_setup_id,
      distanceKm: Number(row.distance_km),
      expectedRunId: run.id,
      combinedInputIdentity: run.combinedInputIdentity,
      pinnedSnapshotHash: run.pinnedSnapshotHash,
      contentFingerprint: run.contentFingerprint,
      shadowBundleVersion: run.shadowBundleVersion,
      ds4ReadStatus: read.status,
      temporalCoverage: tc,
      eventQualityCoverage: eq,
      temporalDetail: payload.temporalCoverageDetail,
      accelOkEvents: payload.acceleration?.okCount ?? 0,
      decelOkEvents: payload.deceleration?.okCount ?? 0,
      accelDegraded: payload.acceleration?.degradedCount ?? 0,
      decelDegraded: payload.deceleration?.degradedCount ?? 0,
      accelArtefact: payload.acceleration?.excludedArtefactCount ?? 0,
      decelArtefact: payload.deceleration?.excludedArtefactCount ?? 0,
    });
  }

  const audi = candidates.filter((c) => c.vehicleId === AUDI);
  const arteon = candidates.filter((c) => c.vehicleId === ARTEON);
  const km = (rows) => Math.round(rows.reduce((s, r) => s + r.distanceKm, 0) * 100) / 100;

  const report = {
    adapterVersion: ADAPTER,
    audiEligible: audi.length,
    arteonEligible: arteon.length,
    totalEligible: candidates.length,
    audiDistanceKm: km(audi),
    arteonDistanceKm: km(arteon),
    totalDistanceKm: km(candidates),
    frozenManifestHash: candidates.length ? manifestHash(candidates) : null,
    historicalExpected: { audiTrips: 30, audiKm: 259, arteonTrips: 12, arteonKm: 50 },
    cohortDelta: {
      audiTripDelta: audi.length - 30,
      arteonTripDelta: arteon.length - 12,
    },
    issues,
    qualityByVehicle,
    candidates,
    readinessFlags: {
      runIdIntegrity: !issues.some((i) => String(i.code).includes('RUN')),
      inputIdentity: !issues.some((i) => String(i.code).includes('IDENTITY')),
      adapterConflicts: !issues.some((i) =>
        ['ADAPTER_ALREADY_PRESENT', 'OTHER_ADAPTER_RUN_EXISTS'].includes(i.code),
      ),
      terminalMarkers: !issues.some((i) => i.code === 'TERMINAL_MARKER'),
      eligibleCountMatchesHistorical:
        audi.length === 30 &&
        arteon.length === 12 &&
        Math.abs(km(audi) - 259) < 0.01 &&
        Math.abs(km(arteon) - 50) < 0.01,
    },
  };

  require('fs').writeFileSync(outPath, JSON.stringify(report, null, 2));
  console.log(
    JSON.stringify({
      audiEligible: report.audiEligible,
      arteonEligible: report.arteonEligible,
      totalEligible: report.totalEligible,
      totalDistanceKm: report.totalDistanceKm,
      frozenManifestHash: report.frozenManifestHash,
      issues: report.issues.length,
      readinessFlags: report.readinessFlags,
    }),
  );
  await prisma.$disconnect();
}

main().catch((e) => {
  console.error(JSON.stringify({ verdict: 'FAILED', error: String(e.message || e) }));
  process.exit(1);
});
